-- Catalog X-watch batch 2026-11-12 (Launchpad HQ)
-- Guarded SQL only. Platforms table. Idempotent. Insert and update statements only.
-- No user tables.
-- ADD: muse-ember, gemini-decisions-api (category ai-apis-developer-services)
-- UPDATE: anthropic-api (Fable 5.2 / Mythos 5.2 price), gemini (Carbon availability and intro end date),
--          claude (Fable 5.2 / Mythos 5.2 availability), openrouter (Stripe announcement + Extractions API note),
--          notion-ai and hermes-agent (Sign in with ChatGPT plan usage)
-- NOTE on existing rows, not new rows: qwen (Qwen4-Max-Preview), minimax (H3-Image), canva-ai-magic-studio (Craft)
-- SKIP as own rows: v0 (partners page lists Vercel, not v0). No separate row for the open-source Sign in with ChatGPT integration.
-- Sources checked 2026-11-12 on vendor pages (see PR body).

INSERT INTO platforms ("id", "slug", "name", "company", "website", "logoUrl", "description", "categoryId", "primaryUse", "costTier", "difficultyLevel", "platformType", "currentPricing", "freeTierFeatures", "usageLimits", "qualityRestrictions", "upgradeTriggers", "installationType", "offlineCapable", "apiAvailable", "keyIntegrations", "privacyLevel", "idealUserTypes", "primaryUseCases", "timeToProductivity", "learningCurve", "directAlternatives", "complementaryTools", "budgetAlternativeTo", "privacyAlternativeTo", "contentTypes", "outputFormats", "languageSupport", "featured", "verified", "createdAt", "updatedAt", "hasMobileApp", "iosAppUrl", "androidAppUrl", "mobileWebFriendly") SELECT $xw$cmxwatch1112museember01$xw$, $xw$muse-ember$xw$, $xw$Muse Ember$xw$, $xw$Meta$xw$, $xw$https://dev.meta.ai/resources/blog/build-with-muse-ember$xw$, NULL, $xw$Meta's Muse Ember is the smallest Muse model on its 2026 launch post, built for high-volume coding subtasks, tool calls, and document summarization and extraction. It accepts text, image, audio, and video. It is in Muse Code, on every Muse Code subscription plan, and on Meta Model API as muse-ember-1.0. The API is OpenAI-compatible at https://api.meta.ai/v1. Per 1M tokens the post lists $0.10 input and $0.50 output for up to 200,000 input tokens, and $0.30 input and $1.50 output above 200,000 input tokens (checked 2026-11-12). The post does not state a free API tier or a maximum context window beyond that price break. The post says to pair it with Muse Wonder or Muse Spark for deeper planning.$xw$, $xw$cmnxhfk4u004q88svb7gaw4ew$xw$, $xw$Small Meta model for high-volume coding and document tasks via API$xw$, $xw$PAID$xw$::"CostTier", $xw$INTERMEDIATE$xw$::"Difficulty", ARRAY[$xw$api$xw$, $xw$web$xw$]::text[], $xw$Meta Model API, per 1M tokens: $0.10 input / $0.50 output up to 200,000 input tokens; $0.30 / $1.50 above 200,000 input tokens (launch post, as of 2026-11-12). Included in all Muse Code subscription plans; those plan prices are not on the post$xw$, $xw$No free API tier is stated on the launch post. Included in all Muse Code subscription plans (plan prices not stated there) (as of 2026-11-12)$xw$, $xw$The lower token rate applies up to 200,000 input tokens; the higher rate applies above that. A maximum context window beyond that price break is not stated (as of 2026-11-12)$xw$, NULL, $xw$Prompts above 200,000 input tokens move to the $0.30 / $1.50 rate; harder planning is handed to Muse Wonder or Muse Spark$xw$, $xw$Meta Model API (muse-ember-1.0) and Muse Code$xw$, false, true, $xw$Muse Code, Meta Model API, OpenAI-compatible clients pointed at https://api.meta.ai/v1$xw$, $xw$MEDIUM$xw$::"PrivacyLevel", ARRAY[$xw$developers$xw$, $xw$agent builders$xw$]::text[], $xw$High-volume coding subtasks; tool calls; document summarization and extraction$xw$, NULL, $xw$Moderate$xw$, ARRAY[]::text[], ARRAY[$xw$Meta AI$xw$]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[$xw$Text$xw$, $xw$Images$xw$, $xw$Audio$xw$, $xw$Video$xw$]::text[], ARRAY[$xw$Text$xw$]::text[], $xw$Languages beyond the English post were not stated (as of 2026-11-12)$xw$, false, true, now(), now(), false, NULL, NULL, true WHERE NOT EXISTS (SELECT 1 FROM platforms WHERE slug = $xw$muse-ember$xw$) AND EXISTS (SELECT 1 FROM categories WHERE id = $xw$cmnxhfk4u004q88svb7gaw4ew$xw$);

INSERT INTO platforms ("id", "slug", "name", "company", "website", "logoUrl", "description", "categoryId", "primaryUse", "costTier", "difficultyLevel", "platformType", "currentPricing", "freeTierFeatures", "usageLimits", "qualityRestrictions", "upgradeTriggers", "installationType", "offlineCapable", "apiAvailable", "keyIntegrations", "privacyLevel", "idealUserTypes", "primaryUseCases", "timeToProductivity", "learningCurve", "directAlternatives", "complementaryTools", "budgetAlternativeTo", "privacyAlternativeTo", "contentTypes", "outputFormats", "languageSupport", "featured", "verified", "createdAt", "updatedAt", "hasMobileApp", "iosAppUrl", "androidAppUrl", "mobileWebFriendly") SELECT $xw$cmxwatch1112gemdecisi01$xw$, $xw$gemini-decisions-api$xw$, $xw$Gemini Decisions API$xw$, $xw$Google$xw$, $xw$https://blog.google/innovation-and-ai/technology/developers-tools/gemini-decisions-api/$xw$, NULL, $xw$Google's Gemini Decisions API is an endpoint for closed-set decisions, powered by Gemini Decision 1 (gemini-decision-1) in the Gemini API in Google AI Studio. One request can score up to 1,000 yes/no, multiple-choice, or rubric questions against one shared multimodal input (text, images, audio, video, or PDFs, up to 256K tokens). Price on the 2026-11-11 launch post: $0.10 per 1M input tokens, and output tokens are not billed. The shared input is billed once per request. Google AI Studio has an API no-cost tier for prototyping. The post says Gemini on Google Cloud support is coming soon, not available yet (checked 2026-11-12). The post says end-to-end latency is 150-250 ms.$xw$, $xw$cmnxhfk4u004q88svb7gaw4ew$xw$, $xw$Gemini API for fast yes/no, choice, and rubric decisions$xw$, $xw$FREEMIUM$xw$::"CostTier", $xw$INTERMEDIATE$xw$::"Difficulty", ARRAY[$xw$api$xw$, $xw$web$xw$]::text[], $xw$Gemini Decision 1: $0.10 per 1M input tokens; output tokens are not billed. Google AI Studio has an API no-cost tier for prototyping (launch post, as of 2026-11-12)$xw$, $xw$API no-cost tier in Google AI Studio for prototyping (as of 2026-11-12)$xw$, $xw$Up to 256K tokens of input and up to 1,000 questions per request. The shared input is billed once. End-to-end latency on the post is 150-250 ms (as of 2026-11-12)$xw$, NULL, $xw$Paid traffic above the AI Studio no-cost prototyping tier$xw$, $xw$Gemini API in Google AI Studio, model gemini-decision-1$xw$, false, true, $xw$Google AI Studio, google-genai SDKs; the post says OpenRouter, LangChain, Vercel, LiteLLM, Pydantic AI, Pipecat, LiveKit, and OpenCode integrations are rolling out$xw$, $xw$MEDIUM$xw$::"PrivacyLevel", ARRAY[$xw$developers$xw$, $xw$teams routing or grading model calls$xw$]::text[], $xw$Tool selection; policy checks; model routing; rubric scoring over text, images, audio, video, or PDFs$xw$, NULL, $xw$Moderate$xw$, ARRAY[$xw$OpenAI API$xw$, $xw$Gemini$xw$]::text[], ARRAY[$xw$Gemini$xw$, $xw$OpenRouter$xw$]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[$xw$Text$xw$, $xw$Images$xw$, $xw$Audio$xw$, $xw$Video$xw$, $xw$PDFs$xw$]::text[], ARRAY[$xw$Scores$xw$]::text[], $xw$Languages beyond the English post were not stated (as of 2026-11-12)$xw$, false, true, now(), now(), false, NULL, NULL, true WHERE NOT EXISTS (SELECT 1 FROM platforms WHERE slug = $xw$gemini-decisions-api$xw$) AND EXISTS (SELECT 1 FROM categories WHERE id = $xw$cmnxhfk4u004q88svb7gaw4ew$xw$);

UPDATE platforms SET "currentPricing" = CASE
  WHEN "currentPricing" LIKE $xw$%Fable 5.1 $10 / $50%$xw$ THEN replace("currentPricing", $xw$Fable 5.1 $10 / $50$xw$, $xw$Fable 5.2 $8 / $40; Mythos 5.2 $8 / $40 (Life Sciences and Cyber Verification Programs)$xw$)
  WHEN COALESCE("currentPricing", $xw$$xw$) = $xw$$xw$ THEN $xw$API per 1M tokens (launch post, as of 2026-11-12): Fable 5.2 $8 in / $40 out; Mythos 5.2 $8 / $40 (Life Sciences and Cyber Verification Programs). Optional fast mode $16 / $80.$xw$
  ELSE "currentPricing" || $xw$ Fable 5.2 $8 / $40 and Mythos 5.2 $8 / $40 per 1M tokens (Mythos via the Life Sciences and Cyber Verification Programs); optional fast mode $16 / $80 (launch post, as of 2026-11-12).$xw$
END, "updatedAt" = now() WHERE slug = $xw$anthropic-api$xw$ AND COALESCE("currentPricing", $xw$$xw$) NOT LIKE $xw$%Fable 5.2 $8 / $40%$xw$;

UPDATE platforms SET description = CASE
  WHEN description LIKE $xw$%which has no stated end date (as of 2026-10-29).%$xw$ THEN replace(description, $xw$which has no stated end date (as of 2026-10-29).$xw$, $xw$which runs through 2026-11-30, then $4 per 1M input tokens and $20 per 1M output tokens. The post says that later price applies to the Carbon model intended for public access only. As of 2026-11-12, Carbon is available via the Gemini API in Google AI Studio and Gemini for business to all paying developers and enterprises, and is rolling out to Google AI Ultra subscribers in the Gemini app, Google Antigravity, and AI Mode in Search.$xw$)
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Gemini 4 Carbon is available via the Gemini API in Google AI Studio and Gemini for business to all paying developers and enterprises, at an introductory $2 per 1M input tokens and $10 per 1M output tokens through 2026-11-30, then $4 and $20. The post says that later price applies to the Carbon model intended for public access only. Carbon is also rolling out to Google AI Ultra subscribers in the Gemini app, Google Antigravity, and AI Mode in Search (as of 2026-11-12).$xw$
  ELSE description || $xw$ Gemini 4 Carbon is available via the Gemini API in Google AI Studio and Gemini for business to all paying developers and enterprises, at an introductory $2 per 1M input tokens and $10 per 1M output tokens through 2026-11-30, then $4 and $20. The post says that later price applies to the Carbon model intended for public access only. Carbon is also rolling out to Google AI Ultra subscribers in the Gemini app, Google Antigravity, and AI Mode in Search (as of 2026-11-12).$xw$
END, "updatedAt" = now() WHERE slug = $xw$gemini$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%through 2026-11-30%$xw$;

UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Claude Fable 5.2, released 2026-11-09, is available on the Claude Platform as claude-fable-5-2, and on AWS, Google Cloud, and Microsoft Azure. The launch post says Fable is available to users generally because of its safeguards. Claude Mythos 5.2 is the same underlying model, with access through the Life Sciences and Cyber Verification Programs. API price on that post: $8 per 1M input tokens and $40 per 1M output tokens; optional fast mode is $16 and $80, and Mythos fast mode is only for organizations in those programs (as of 2026-11-12).$xw$
  ELSE description || $xw$ Claude Fable 5.2, released 2026-11-09, is available on the Claude Platform as claude-fable-5-2, and on AWS, Google Cloud, and Microsoft Azure. The launch post says Fable is available to users generally because of its safeguards. Claude Mythos 5.2 is the same underlying model, with access through the Life Sciences and Cyber Verification Programs. API price on that post: $8 per 1M input tokens and $40 per 1M output tokens; optional fast mode is $16 and $80, and Mythos fast mode is only for organizations in those programs (as of 2026-11-12).$xw$
END, "updatedAt" = now() WHERE slug = $xw$claude$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%Claude Fable 5.2, released 2026-11-09%$xw$;

UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Note (2026-11-12): OpenRouter's 2026-08-19 post says it is joining Stripe, that the name, product, mission, roadmap, and existing integrations stay the same, and that the transaction was still subject to customary closing conditions. The Extractions API is in alpha (announced 2026-11-10) for pulling typed fields out of text, images, and PDFs, launching with models from Cloudflare, Inception, and ScaleDown. It is not a separate catalog row.$xw$
  ELSE description || $xw$ Note (2026-11-12): OpenRouter's 2026-08-19 post says it is joining Stripe, that the name, product, mission, roadmap, and existing integrations stay the same, and that the transaction was still subject to customary closing conditions. The Extractions API is in alpha (announced 2026-11-10) for pulling typed fields out of text, images, and PDFs, launching with models from Cloudflare, Inception, and ScaleDown. It is not a separate catalog row.$xw$
END, "updatedAt" = now() WHERE slug = $xw$openrouter$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%Extractions API is in alpha%$xw$;

UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Note (2026-11-12): OpenAI's Sign in with ChatGPT partners directory lists Notion among apps where eligible ChatGPT Go, Plus, Pro, and Business subscribers can use their ChatGPT plan for AI requests. Signing in and using the plan are separate permissions, and a Business admin has to allow the app.$xw$
  ELSE description || $xw$ Note (2026-11-12): OpenAI's Sign in with ChatGPT partners directory lists Notion among apps where eligible ChatGPT Go, Plus, Pro, and Business subscribers can use their ChatGPT plan for AI requests. Signing in and using the plan are separate permissions, and a Business admin has to allow the app.$xw$
END, "updatedAt" = now() WHERE slug = $xw$notion-ai$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%partners directory lists Notion%$xw$;

