UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Note (2026-11-12): Qwen4-Max-Preview (model id qwen4-max-preview) is a time-limited preview on Alibaba Cloud Model Studio, Token Plan only. Pay-as-you-go is not supported. The preview runs from 10:00 on 2026-11-11 to 24:00 on 2026-11-25 (UTC+8), and the page says the model is retired after the preview ends. Context length is 1M tokens. Maximum output is 393,216 tokens, shared by thinking and the final answer. Recorded as a note on this row, not a new row, because the preview ends.$xw$
  ELSE description || $xw$ Note (2026-11-12): Qwen4-Max-Preview (model id qwen4-max-preview) is a time-limited preview on Alibaba Cloud Model Studio, Token Plan only. Pay-as-you-go is not supported. The preview runs from 10:00 on 2026-11-11 to 24:00 on 2026-11-25 (UTC+8), and the page says the model is retired after the preview ends. Context length is 1M tokens. Maximum output is 393,216 tokens, shared by thinking and the final answer. Recorded as a note on this row, not a new row, because the preview ends.$xw$
END, "updatedAt" = now() WHERE slug = $xw$qwen$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%qwen4-max-preview%$xw$;

UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Note (2026-11-12): MiniMax H3-Image, released 2026-11-11, is an open-weight image model. The launch post says it can generate a 4K (4096 by 4096) image in under 10 seconds, supports up to 16 reference images, and is available through the MiniMax API Platform, MiniMax Code, and Hailuo AI. For launch week it offers 50% off the standard price for image generation at 4K and above. The post does not give a calendar end date or a dollar price. Recorded as a note on this row, not a new row.$xw$
  ELSE description || $xw$ Note (2026-11-12): MiniMax H3-Image, released 2026-11-11, is an open-weight image model. The launch post says it can generate a 4K (4096 by 4096) image in under 10 seconds, supports up to 16 reference images, and is available through the MiniMax API Platform, MiniMax Code, and Hailuo AI. For launch week it offers 50% off the standard price for image generation at 4K and above. The post does not give a calendar end date or a dollar price. Recorded as a note on this row, not a new row.$xw$
END, "updatedAt" = now() WHERE slug = $xw$minimax$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%H3-Image%$xw$;

UPDATE platforms SET description = CASE
  WHEN COALESCE(description, $xw$$xw$) = $xw$$xw$ THEN $xw$Note (2026-11-12): Canva Craft (model id craft_v1_2k) is Canva's image-generation model, available through the preview Image generation API. The preview can change without notice, and apps that use it cannot pass public-app review. Each generation uses the user's AI credit allowance. Recorded as a note on this row, not a new row.$xw$
  ELSE description || $xw$ Note (2026-11-12): Canva Craft (model id craft_v1_2k) is Canva's image-generation model, available through the preview Image generation API. The preview can change without notice, and apps that use it cannot pass public-app review. Each generation uses the user's AI credit allowance. Recorded as a note on this row, not a new row.$xw$
END, "updatedAt" = now() WHERE slug = $xw$canva-ai-magic-studio$xw$ AND COALESCE(description, $xw$$xw$) NOT LIKE $xw$%craft_v1_2k%$xw$;
